var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    errors: [],
    coments: [],
  },
  methods: {
    getData() {
      const path =
        window.location.origin + "/dashboard/comments/data";
      axios
        .get(path)
        .then((response) => {
          this.coments = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    addNewQues() {
      const path = window.location.origin + "/dashboard/comments";
      axios
        .post(path)
        .then((response) => {
          this.coments = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    deleteQues(index, id) {
      const path = window.location.origin + "/dashboard/comments/"+id;
      axios
        .delete(path)
        .then((response) => {
          this.coments.splice(index, 1);
          this.$notify({
            group: 'notification',
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000
          });
        })
        .catch((error) => {
          console.log(error);
        });
    },
    updateData(index) {
      const path = window.location.origin + "/dashboard/comments/"+this.coments[index].id;
      axios
        .post(path, {
          data: this.coments[index].value,
        })
        .then((response) => {
          this.$notify({
            group: 'notification',
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000
          })
        })
        .catch((error) => {
          console.log(error);
        });
    },
  },
  created() {
    this.getData();
  },
});
